from pathlib import Path


def replace_once(path: str, old: str, new: str):
    p = Path(path)
    text = p.read_text()
    if text.count(old) != 1:
        raise SystemExit(f"anchor not found exactly once in {path}: {old[:120]!r}")
    p.write_text(text.replace(old, new, 1))

# Shared candidate contract: source kind is explicit while legacy producers remain source-compatible.
replace_once(
    "packages/shared-types/src/qa-evidence-candidates.ts",
    "export type QaEvidenceAttributeValue = string | number | boolean | null;\n\nexport interface QaEvidenceCandidateView {\n  key: string;",
    "export type QaEvidenceAttributeValue = string | number | boolean | null;\nexport type QaEvidenceCandidateSourceKind = \"structuredCandidate\" | \"documentChunk\";\n\nexport interface QaEvidenceCandidateView {\n  key: string;\n  /** Normalized source kind. Service normalization fills legacy structured adapters. */\n  sourceKind?: QaEvidenceCandidateSourceKind;",
)

# Document adapter: exact chunk locator + lexical/hybrid retrieval without pgvector.
semantic = Path("apps/backend/src/plugins/qa/documents/semantic.ts")
semantic.write_text('''import type {\n  QaEvidenceCandidateResultView,\n  QaEvidenceSourceDomain,\n} from "@dse-pms/shared-types";\nimport { prisma } from "../../../core/db/prisma.ts";\nimport {\n  configuredQaEmbeddingProvider,\n  cosineSimilarity,\n  type QaEmbeddingProvider,\n} from "./embedding.ts";\n\nexport interface QaSemanticEvidenceDefinition {\n  id: string;\n  evidenceType: string;\n  description: string;\n  sourceDomain: QaEvidenceSourceDomain;\n  expectationStatement: string;\n}\n\nfunction documentTypeForDomain(sourceDomain: QaEvidenceSourceDomain): string | null {\n  if (sourceDomain === "policy") return "policy";\n  if (sourceDomain === "survey") return "survey";\n  if (sourceDomain === "minutes") return "minutes";\n  return null;\n}\n\nfunction lexicalTerms(value: string): string[] {\n  return [...new Set(value.toLowerCase().match(/[a-z0-9]{3,}/g) ?? [])];\n}\n\nexport function lexicalEvidenceScore(query: string, text: string): number {\n  const terms = lexicalTerms(query);\n  if (terms.length === 0) return 0;\n  const haystack = text.toLowerCase();\n  const matched = terms.filter((term) => haystack.includes(term)).length;\n  return matched / terms.length;\n}\n\nexport async function retrieveSemanticDocumentEvidence(\n  programmeId: string,\n  definition: QaSemanticEvidenceDefinition,\n  topK = 10,\n  provider: QaEmbeddingProvider | null = configuredQaEmbeddingProvider(),\n): Promise<QaEvidenceCandidateResultView> {\n  const query = `${definition.expectationStatement}\\nExpected evidence: ${definition.description}`;\n  const requiredDocumentType = documentTypeForDomain(definition.sourceDomain);\n  const chunks = await prisma.qaDocumentChunk.findMany({\n    where: {\n      document: {\n        programmeId,\n        ...(requiredDocumentType ? { documentType: requiredDocumentType } : {}),\n      },\n    },\n    include: { document: true },\n  });\n\n  let queryVector: number[] | null = null;\n  if (provider) {\n    try {\n      queryVector = (await provider.embed([query]))[0] ?? null;\n    } catch {\n      // Fail soft to lexical retrieval. The pilot must remain usable without\n      // pgvector or a live embedding service; provenance remains unchanged.\n      queryVector = null;\n    }\n  }\n\n  const ranked = chunks\n    .map((chunk) => {\n      const lexical = lexicalEvidenceScore(query, chunk.text);\n      const semantic =\n        provider && queryVector && chunk.embeddingModel === provider.model && chunk.embedding.length > 0\n          ? cosineSimilarity(queryVector, chunk.embedding)\n          : null;\n      const semanticNormalized = semantic === null || !Number.isFinite(semantic)\n        ? null\n        : Math.max(0, Math.min(1, (semantic + 1) / 2));\n      const score = semanticNormalized === null ? lexical : (semanticNormalized * 0.75) + (lexical * 0.25);\n      return { chunk, score, lexical, semantic: semanticNormalized };\n    })\n    .filter((item) => item.score > 0)\n    .sort((a, b) =>\n      b.score - a.score ||\n      a.chunk.documentId.localeCompare(b.chunk.documentId) ||\n      a.chunk.chunkIndex - b.chunk.chunkIndex\n    )\n    .slice(0, topK);\n\n  const retrievalMode = queryVector ? "hybrid" : "lexical";\n  return {\n    programmeId,\n    expectedEvidenceId: definition.id,\n    evidenceType: definition.evidenceType,\n    sourceDomain: definition.sourceDomain,\n    status: "supported",\n    reason: queryVector\n      ? `Hybrid document retrieval ranked programme chunks using lexical relevance and embedding model ${provider?.model}.`\n      : "Lexical document retrieval ranked programme chunks without requiring pgvector or an embedding provider.",\n    candidates: ranked.map(({ chunk, score, lexical, semantic }) => ({\n      key: `${definition.evidenceType}:QaDocumentChunk:${chunk.id}`,\n      sourceKind: "documentChunk",\n      evidenceType: definition.evidenceType,\n      sourceDomain: definition.sourceDomain,\n      title: `${chunk.document.title} · chunk ${chunk.chunkIndex + 1}`,\n      summary: chunk.text.length > 700 ? `${chunk.text.slice(0, 697)}…` : chunk.text,\n      entityType: "QaDocumentChunk",\n      entityId: chunk.id,\n      route: null,\n      reportingDate:\n        chunk.document.reportingEnd?.toISOString() ?? chunk.document.updatedAt.toISOString(),\n      scope: { programmeId },\n      provenance: {\n        authority: "uploadedExternalDocument",\n        ownerUnit: "DSE",\n        version: chunk.document.version,\n        approvalStatus: null,\n        sourceUri: `qa-document:${chunk.documentId}#chunk=${chunk.id}`,\n      },\n      periodKey: chunk.document.reportingEnd\n        ? String(chunk.document.reportingEnd.getUTCFullYear())\n        : String(chunk.document.updatedAt.getUTCFullYear()),\n      attributes: {\n        documentId: chunk.documentId,\n        documentType: chunk.document.documentType,\n        documentVersion: chunk.document.version,\n        chunkIndex: chunk.chunkIndex,\n        pageNumber: chunk.pageNumber,\n        sectionLabel: chunk.sectionLabel,\n        startOffset: chunk.startOffset,\n        endOffset: chunk.endOffset,\n        relevance: Number(score.toFixed(6)),\n        lexicalScore: Number(lexical.toFixed(6)),\n        semanticScore: semantic === null ? null : Number(semantic.toFixed(6)),\n        retrievalMode,\n        embeddingModel: chunk.embeddingModel,\n        contentHash: chunk.document.contentHash,\n      },\n    })),\n  };\n}\n''')

# Normalize source kind and deterministically de-duplicate candidate keys.
replace_once(
    "apps/backend/src/plugins/qa/evidence/service.ts",
    '''function normalizeCandidateSemantics(\n  programmeId: string,\n  result: QaEvidenceCandidateResultView,\n): QaEvidenceCandidateResultView {\n  return {\n    ...result,\n    candidates: result.candidates.map((candidate) => ({\n      ...candidate,\n      scope: candidate.scope ?? inferScope(programmeId, candidate),\n      provenance: candidate.provenance ?? inferProvenance(candidate),\n      periodKey: candidate.periodKey ?? inferPeriodKey(candidate),\n    })),\n  };\n}''',
    '''export function normalizeCandidateSemantics(\n  programmeId: string,\n  result: QaEvidenceCandidateResultView,\n): QaEvidenceCandidateResultView {\n  const normalized = result.candidates.map((candidate) => ({\n    ...candidate,\n    sourceKind: candidate.sourceKind ?? (candidate.entityType === "QaDocumentChunk" ? "documentChunk" as const : "structuredCandidate" as const),\n    scope: candidate.scope ?? inferScope(programmeId, candidate),\n    provenance: candidate.provenance ?? inferProvenance(candidate),\n    periodKey: candidate.periodKey ?? inferPeriodKey(candidate),\n  }));\n  // Candidate keys are the stable identity across adapters. Preserve the first\n  // ranked occurrence and drop later duplicates deterministically.\n  const byKey = new Map(normalized.map((candidate) => [candidate.key, candidate]));\n  return { ...result, candidates: [...byKey.values()] };\n}''',
)

# Analysis persistence must preserve the candidate source kind.
replace_once(
    "apps/backend/src/plugins/qa/analysis/deterministic-engine.ts",
    '      sourceKind: "structuredCandidate" as const,',
    '      sourceKind: candidate.sourceKind ?? "structuredCandidate",',
)

# Pure contract tests: mixed source kinds, exact document locator, deterministic duplicate policy, lexical fallback.
Path("apps/backend/src/plugins/qa/evidence/unified-candidates.test.ts").write_text('''import { describe, expect, test } from "bun:test";\nimport type { QaEvidenceCandidateResultView } from "@dse-pms/shared-types";\nimport { lexicalEvidenceScore } from "../documents/semantic.ts";\nimport { normalizeCandidateSemantics } from "./service.ts";\n\nfunction result(candidates: QaEvidenceCandidateResultView["candidates"]): QaEvidenceCandidateResultView {\n  return {\n    programmeId: "dse",\n    expectedEvidenceId: "evidence-1",\n    evidenceType: "policy",\n    sourceDomain: "policy",\n    status: "supported",\n    reason: "test",\n    candidates,\n  };\n}\n\ndescribe("unified QA evidence candidates", () => {\n  test("normalizes structured and document source kinds through one contract", () => {\n    const normalized = normalizeCandidateSemantics("dse", result([\n      { key: "structured:1", evidenceType: "policy", sourceDomain: "outcomes", title: "Structured", summary: "", entityType: "Course", entityId: "course-1", route: "/courses/course-1", reportingDate: "2026-01-01T00:00:00.000Z", attributes: {} },\n      { key: "document:1", sourceKind: "documentChunk", evidenceType: "policy", sourceDomain: "policy", title: "Document", summary: "chunk", entityType: "QaDocumentChunk", entityId: "chunk-1", route: null, reportingDate: "2026-01-01T00:00:00.000Z", attributes: { documentId: "doc-1", documentVersion: "2", pageNumber: 4, sectionLabel: "Review", startOffset: 120, endOffset: 420 } },\n    ]));\n    expect(normalized.candidates.map((candidate) => candidate.sourceKind)).toEqual(["structuredCandidate", "documentChunk"]);\n    expect(normalized.candidates[1]?.attributes.startOffset).toBe(120);\n    expect(normalized.candidates[1]?.attributes.endOffset).toBe(420);\n  });\n\n  test("deduplicates stable candidate keys deterministically", () => {\n    const duplicate = { key: "same", evidenceType: "policy", sourceDomain: "outcomes" as const, title: "first", summary: "", entityType: "Course", entityId: "course-1", route: null, reportingDate: null, attributes: {} };\n    const normalized = normalizeCandidateSemantics("dse", result([duplicate, { ...duplicate, title: "second" }]));\n    expect(normalized.candidates).toHaveLength(1);\n    expect(normalized.candidates[0]?.title).toBe("second");\n  });\n\n  test("lexical fallback ranks relevant document text without embeddings", () => {\n    const query = "student progression completion outcomes";\n    expect(lexicalEvidenceScore(query, "Annual student progression and completion outcomes report")).toBeGreaterThan(0.5);\n    expect(lexicalEvidenceScore(query, "Laboratory equipment inventory")).toBe(0);\n  });\n});\n''')
